    missing = [s for s in stored if s not in found]
    for s in stored:
        for p in found.get(s, []):
            out["copies"].append({"sha256": s, "path": p, "tree": tree})
    if missing:
        return out, "BRIEF_NOT_COMMITTED", "commit 済みの写しがない: " + ",".join(s[:12] for s in missing)
